"""RV2-B (routing v2 stage 2: fingerprint shortlist). Pre-registration: PREREG.md (generated by `prereg`, read-only afterwards).

    python research/growmoe_results/rv2b/run_rv2b.py scaling                 # runs scaling_check.py (wall-clock and MACs at 8-500 experts)
    python research/growmoe_results/rv2b/run_rv2b.py dev    [--smoke]        # exact vs cascade k=1,4,8 on dev seeds -> dev_k.json
    python research/growmoe_results/rv2b/run_rv2b.py prereg                  # k, shipped minimum E, expected outcomes -> bars_rv2b.json, PREREG.md
    python research/growmoe_results/rv2b/run_rv2b.py run    [--smoke] [--seeds 40-59]
    python research/growmoe_results/rv2b/run_rv2b.py report [--smoke]

Both arms share the training budget (the cascade does not change learning) and the stage-1 default in force when `prereg` runs.
"""

import argparse
import hashlib
import json
import subprocess
import sys
import time
from pathlib import Path

HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[2]
for _p in (HERE.parent / "rv2a", HERE.parent / "m2a", HERE.parent / "m0", ROOT):
    sys.path.insert(0, str(_p))

import numpy as np                                                                      # noqa: E402
import torch                                                                            # noqa: E402

import run_m0 as M                                                                      # noqa: E402
import run_rv2a as A                                                                    # noqa: E402
from growmoe.accounting import measured_gate_macs_per_input                              # noqa: E402
from growmoe.config import PhyloCfg                                                     # noqa: E402
from growmoe.fairfight import BARS_RV2B, rv2b_decision, rv2b_verdicts, run_fast, run_record  # noqa: E402
from growmoe.metrics import paired_diff                                                 # noqa: E402
from growmoe.pools.phylo import PhyloMoE                                                # noqa: E402

BASE = dict(q=0.02, alpha_spawn=0.01, m_min=32, route_rule="accept_then_logf", arm_monitor_after_infancy=True,   # M0's A_KW without its historical pins
            router=False, spawn_rule="probe", growth_rule="probe")                      # stage 4 did not exist then (router and transfer rule default ON since 2026-10-21, RV2-D)
STREAMS = ["F-30", "S2-30", "F-15", "OV-0.3", "S1", "S2-5"]
DEV_STREAMS = ["F-30", "S2-30", "F-15"]
ARMS = ("A_exact", "A_cascade")
LABEL = {"A_exact": "A_exact (scan every expert)", "A_cascade": "A_cascade (fingerprint shortlist)"}
SMOKE_SEEDS = (40, 41)
FORCE_MIN = 8                                                                           # the accuracy test exercises the cascade from 8 experts up


def out_dir(args) -> Path:
    d = HERE / "_smoke" if args.smoke else HERE
    d.mkdir(parents=True, exist_ok=True)
    return d


def steps_for(name: str) -> int:
    """The budget of whichever stage-1 arm is the default now (so A_exact is exactly today's pool)."""
    fam = A.family(name)
    if PhyloCfg(router=False, spawn_rule="probe", growth_rule="probe").batch_vote:
        return json.loads((ROOT / "research/growmoe_results/rv2a/tuning_rv2a.json").read_text(encoding="utf-8"))["A_vote"][fam]["steps"]
    return json.loads(A.M2A_TUNING.read_text(encoding="utf-8"))["A_new"][fam]["steps"]


def factory(arm: str, st, seed: int, steps: int, k: int):
    kw = dict(BASE)
    if arm == "A_exact":
        kw["gate_shortlist"] = 0
    else:
        kw.update(gate_shortlist=2, gate_fingerprint_k=k, gate_shortlist_min_experts=FORCE_MIN)
    return lambda: PhyloMoE(PhyloCfg(seed=seed, d=st.d, n_classes=st.n_classes, inner_steps=steps, **kw))


def run_task(spec: dict) -> dict:
    name, seed, smoke = spec["stream"], spec["seed"], spec["smoke"]
    st = A.get_stream(name, seed, smoke)
    steps, t0, recs = steps_for(name), time.perf_counter(), []
    for arm in spec["arms"]:
        k = int(arm.split("_k")[1]) if "_k" in arm else spec["k"]
        holder = []

        def make(arm=arm, k=k):
            holder.append(factory(arm.split("_k")[0], st, seed, steps, k)())
            return holder[-1]

        res = run_fast(make, st, seed, eval_every="final")
        pool = holder[0]
        recs.append(run_record(name, arm, seed, res, steps=steps, k=k, gate_macs_pred=measured_gate_macs_per_input(pool, "predict"),
                               gate_macs_obs=measured_gate_macs_per_input(pool, "observe")))
    return {"spec": {k_: spec[k_] for k_ in ("stream", "seed", "smoke", "arms")}, "records": recs, "seconds": time.perf_counter() - t0, "peak_mb": M._peak_mb()}


def cmd_scaling(args) -> None:
    k = json.loads((HERE / "bars_rv2b.json").read_text(encoding="utf-8"))["k"] if (HERE / "bars_rv2b.json").exists() else 4
    subprocess.run([sys.executable, str(HERE / "scaling_check.py"), "--k", str(k)], check=True)


def cmd_dev(args) -> None:
    out = out_dir(args)
    seeds = M.SMOKE_DEV if args.smoke else M.DEV_SEEDS
    assert all(s >= 100 for s in seeds)
    arms = ["A_exact", "A_cascade_k1", "A_cascade_k4", "A_cascade_k8"]
    specs = [dict(stream=n, seed=s, smoke=args.smoke, arms=arms, k=4) for n in DEV_STREAMS for s in seeds]
    tasks = M._parallel(run_task, specs, lambda s: out / "dev" / f"{s['stream']}__{s['seed']}.json", args.workers, args.threads, "dev", args.force,
                        tag_of=lambda s: f"{s['stream']} seed {s['seed']}")
    runs = [r for t in tasks for r in t["records"]]
    table = {n: {a: 100.0 * float(np.mean([r["acc"] for r in runs if r["stream"] == n and r["method"] == a])) for a in arms} for n in DEV_STREAMS}
    macs = {n: {a: float(np.mean([r["gate_macs_pred"] for r in runs if r["stream"] == n and r["method"] == a])) for a in arms} for n in DEV_STREAMS}
    ok = [k for k in (1, 4, 8) if all(table[n]["A_exact"] - table[n][f"A_cascade_k{k}"] <= 0.3 for n in ("F-30", "S2-30"))]
    chosen = min(ok) if ok else 8                                                       # cheapest k within 0.3 point of exact on the >= 16-expert dev streams
    (out / "dev_k.json").write_text(json.dumps({"accuracy": table, "gate_macs_pred": macs, "k": chosen, "satisfying": ok}, indent=1), encoding="utf-8")
    for n in DEV_STREAMS:
        print(n, {a: round(v, 1) for a, v in table[n].items()}, {a: round(v / macs[n]["A_exact"], 3) for a, v in macs[n].items()})
    print("chosen k:", chosen, "(satisfying:", ok, ")")


def cmd_prereg(args) -> None:
    out = out_dir(args)
    dev = json.loads((out / "dev_k.json").read_text(encoding="utf-8"))
    scaling = json.loads((HERE / "scaling_check.json").read_text(encoding="utf-8"))
    k = dev["k"]
    crossing = [int(e) for e, row in scaling["rows"].items() if all(row[b]["ratio_time"] <= 0.9 for b in ("64", "1024"))]
    min_experts = min(crossing) if crossing else 10 ** 9                                # never auto-enabled if the cascade is never faster
    gaps = [dev["accuracy"][n]["A_exact"] - dev["accuracy"][n][f"A_cascade_k{k}"] for n in DEV_STREAMS]
    ratios = {n: dev["gate_macs_pred"][n][f"A_cascade_k{k}"] / dev["gate_macs_pred"][n]["A_exact"] for n in DEV_STREAMS}
    expected = {"C1": "PASS" if max(gaps) <= 1.0 else "FAIL", "C2": "PASS",
                "C3": "PASS" if all(ratios[n] <= BARS_RV2B["C3"][n] for n in ratios) else "FAIL",
                "C4": "PASS" if rv2b_verdicts([], scaling)["C4"]["verdict"] == "PASS" else "FAIL", "G": "PASS"}
    bars_path = out / "bars_rv2b.json"
    base_default = PhyloCfg(router=False, spawn_rule="probe", growth_rule="probe").batch_vote
    bars_path.write_text(json.dumps({"k": k, "min_experts": min_experts, "force_min_for_accuracy_test": FORCE_MIN, "expected": expected, "batch_vote_default": base_default,
                                     "dev_gaps_points": dict(zip(DEV_STREAMS, gaps)), "dev_ratios": ratios, "written": time.strftime("%Y-%m-%d %H:%M:%S")}, indent=1),
                         encoding="utf-8")
    rules = {kk: v["rule"] for kk, v in rv2b_verdicts([], scaling).items()}
    L = ["# RV2-B pre-registration (generated by run_rv2b.py prereg; written before any confirmatory seed ran)\n",
         f"Spec section 5. Arms: `A_exact` (gate_shortlist=0) and `A_cascade` (gate_shortlist=2, gate_fingerprint_k={k}, gate_shortlist_min_experts={FORCE_MIN} for this accuracy test). "
         f"Both on top of the stage-1 default in force now (batch_vote={base_default}) with that arm's tuned budget. Confirmatory seeds 40-59; dev seeds 100-102; batch 64.\n",
         f"Rule for k: the cheapest k in {{1, 4, 8}} whose accuracy is within 0.3 point of exact on every dev stream with >= 16 experts (F-30, S2-30): chosen k = {k}. "
         f"Shipped `gate_shortlist_min_experts` = smallest E in the scaling grid where the cascade's gate wall-clock is at most 0.9 x exact at B = 64 and 1024: {min_experts}.\n",
         "## Statements\n", "| ID | Rule | Expected |", "|---|---|---|"] + [f"| {kk} | {rule} | {expected[kk]} |" for kk, rule in rules.items()] + [
         "", "## Decision rule (verbatim from the spec)\n",
         "Adopt iff C1 passes; C3 or C4 failing with C1 passing keeps the cascade opt-in; G failing is a bug and stops the stage. C2 is reported, not gating.\n",
         "## Provenance\n", f"spec {A._sha(ROOT / 'docs/superpowers/specs/2026-10-10-routing-v2-design.md')}; phylo.py {A._sha(ROOT / 'growmoe/pools/phylo.py')}; "
         f"fingerprint.py {A._sha(ROOT / 'growmoe/fingerprint.py')}; config.py {A._sha(ROOT / 'growmoe/config.py')}; fairfight.py {A._sha(ROOT / 'growmoe/fairfight.py')}; "
         f"this script {A._sha(Path(__file__))}; scaling_check.json {A._sha(HERE / 'scaling_check.json')}; bars_rv2b.json {A._sha(bars_path)}.\n"]
    (out / "PREREG.md").write_text("\n".join(L), encoding="utf-8")
    print(f"bars_rv2b.json frozen, sha256 {M.freeze_check(bars_path)[:16]}")
    print("k", k, "min_experts", min_experts, "expected", expected)


def cmd_run(args) -> None:
    out = out_dir(args)
    bars_path = out / "bars_rv2b.json"
    if args.smoke:
        seeds, k = SMOKE_SEEDS, 4
    else:
        if not bars_path.exists():
            sys.exit("bars_rv2b.json is missing: run scaling, dev and prereg first")
        print(f"bars_rv2b.json frozen, sha256 {M.freeze_check(bars_path)[:16]}", flush=True)
        seeds, k = M.parse_seeds(args.seeds), json.loads(bars_path.read_text(encoding="utf-8"))["k"]
        assert all(40 <= s <= 59 for s in seeds), "the stage-2 confirmatory seeds are 40-59"
    order = {n: i for i, n in enumerate(STREAMS)}
    specs = sorted([dict(stream=n, seed=s, smoke=args.smoke, arms=list(ARMS), k=k) for n in STREAMS for s in seeds], key=lambda s: (order[s["stream"]], s["seed"]))
    M._parallel(run_task, specs, lambda s: out / "runs" / f"{s['stream']}__{s['seed']}.json", args.workers, args.threads, "run", args.force,
                tag_of=lambda s: f"{s['stream']} seed {s['seed']}")


def cmd_report(args) -> None:
    out = out_dir(args)
    tasks = [json.loads(p.read_text(encoding="utf-8")) for p in sorted((out / "runs").glob("*.json"))]
    runs = [r for t in tasks for r in t["records"]]
    bp, sp = out / "bars_rv2b.json", HERE / "scaling_check.json"
    doc = json.loads(bp.read_text(encoding="utf-8")) if bp.exists() else {"expected": {}, "k": None, "min_experts": None}
    scaling = json.loads(sp.read_text(encoding="utf-8")) if sp.exists() else None
    result = rv2b_verdicts(runs, scaling, expected=doc["expected"])
    decision = rv2b_decision(result, doc["k"], doc["min_experts"])
    (out / "rv2b_runs.json").write_text(json.dumps({"runs": runs, "bars": doc, "verdicts": result, "decision": decision}, indent=1), encoding="utf-8")
    by: dict = {}
    for r in runs:
        by.setdefault((r["stream"], r["method"]), []).append(r)
    L = ["# RV2-B results (generated by run_rv2b.py; do not edit by hand)\n"]
    if args.smoke:
        L.append("> **SMOKE RUN. Tiny streams and grids. These numbers mean nothing.**\n")
    L.append(f"* PREREG.md sha256 {A._sha(out / 'PREREG.md')}; bars_rv2b.json {A._sha(bp)}; scaling_check.json {A._sha(sp)}; this script {A._sha(Path(__file__))}; "
             f"phylo.py {A._sha(ROOT / 'growmoe/pools/phylo.py')}; fingerprint.py {A._sha(ROOT / 'growmoe/fingerprint.py')}.\n")
    L += ["## Verdicts (computed by `growmoe.fairfight.rv2b_verdicts`)\n", "| ID | Rule | Verdict | Expected | Detail |", "|---|---|---|---|---|"]
    for kk, v in result.items():
        mark = {True: "as expected", False: "**AGAINST expectation**", None: "-"}[v["as_expected"]]
        L.append(f"| {kk} | {v['rule']} | **{v['verdict']}** | {v['expected']} ({mark}) | `{json.dumps(v['detail'])}` |")
    L += [f"\n**Decision.** {decision}\n", "## Results per stream (final accuracy %; gate MACs per input measured by the pool's counters)\n",
          "| Stream | Arm | Accuracy % | Experts | Gate kMACs / input (predict) | Gate kMACs / input (learning) | Seconds per run | n |", "|---|---|---|---|---|---|---|---|"]
    for name in STREAMS:
        for arm in ARMS:
            rows = by.get((name, arm))
            if rows:
                L.append(f"| {name} | {LABEL[arm]} | {M._fmt_ci([r['acc'] for r in rows])} | {M._mean(rows, 'n_experts'):.1f} | {M._mean(rows, 'gate_macs_pred') / 1000:.1f} | "
                         f"{M._mean(rows, 'gate_macs_obs') / 1000:.1f} | {M._mean(rows, 'wall_clock'):.0f} | {len(rows)} |")
    L.append("")
    for name in STREAMS:
        ra, rb = {r["seed"]: r for r in by.get((name, "A_cascade"), [])}, {r["seed"]: r for r in by.get((name, "A_exact"), [])}
        common = sorted(set(ra) & set(rb))
        if len(common) >= 2:
            d = paired_diff([100 * ra[s]["acc"] for s in common], [100 * rb[s]["acc"] for s in common])
            L.append(f"* {name}: A_cascade - A_exact {d['mean_diff']:+.2f} pts [{d['ci_lo']:+.2f}, {d['ci_hi']:+.2f}], p = {d['p_t']:.3g}, n = {d['n']}")
    if scaling:
        L += ["", "## Scaling check (synthetic pools, no training)\n", "| Experts | B | exact ms | cascade ms | time ratio | MACs ratio |", "|---|---|---|---|---|---|"]
        for e, row in scaling["rows"].items():
            for b, v in row.items():
                L.append(f"| {e} | {b} | {1000 * v['exact_s']:.2f} | {1000 * v['cascade_s']:.2f} | {v['ratio_time']:.2f} | {v['ratio_macs']:.3f} |")
    (out / "RESULTS_RV2B.md").write_text("\n".join(L) + "\n", encoding="utf-8")
    print(f"wrote {out / 'RESULTS_RV2B.md'}")
    for kk, v in result.items():
        print(f"  {kk}: {v['verdict']:15s} (expected {v['expected']})")
    print(" ", decision)


def main() -> None:
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("cmd", choices=["scaling", "dev", "prereg", "run", "report"])
    ap.add_argument("--smoke", action="store_true")
    ap.add_argument("--workers", type=int, default=2)
    ap.add_argument("--threads", type=int, default=3)
    ap.add_argument("--seeds", default="40-59")
    ap.add_argument("--force", action="store_true")
    args = ap.parse_args()
    torch.set_num_threads(args.threads)
    {"scaling": cmd_scaling, "dev": cmd_dev, "prereg": cmd_prereg, "run": cmd_run, "report": cmd_report}[args.cmd](args)


if __name__ == "__main__":
    main()
